#include "elit21/aliexpress/auth/AliExpressTokenManager.h"
namespace elit21::aliexpress::auth {void AliExpressTokenManager::store(AliExpressToken t,std::chrono::system_clock::time_point i){std::lock_guard l(mutex_);token_=std::move(t);issued_at_=i;}std::optional<AliExpressToken>AliExpressTokenManager::get()const{std::lock_guard l(mutex_);return token_;}bool AliExpressTokenManager::needsRefresh(std::chrono::minutes lead)const{std::lock_guard l(mutex_);if(!token_||!token_->valid())return true;return std::chrono::system_clock::now()+lead>=issued_at_+std::chrono::seconds(token_->expires_in_seconds);}}
